import{_ as t,a,c as n,ac as s}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第四册：流利英语 · Lesson 12 Banks and their customers","description":"学习 unless 与条件从句，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第四册：流利英语 · Lesson 12 Banks and their customers","description":"学习 unless 与条件从句，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第4册课时","summary":"学习 unless 与条件从句，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · Lesson 11 How to grow old","link":"/life/english/new-concept/book-4/unit-02/lesson-011"},"next":{"text":"第四册：流利英语 · Lesson 13 The search for oil","link":"/life/english/new-concept/book-4/unit-02/lesson-013"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · Lesson 11 How to grow old","link":"/life/english/new-concept/book-4/unit-02/lesson-011"},"next":{"text":"第四册：流利英语 · Lesson 13 The search for oil","link":"/life/english/new-concept/book-4/unit-02/lesson-013"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-02/lesson-012.md","filePath":"life/english/new-concept/book-4/unit-02/lesson-012.md"}'),o={name:"life/english/new-concept/book-4/unit-02/lesson-012.md"};function i(l,e,r,d,h,c){return a(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="第四册-流利英语-·-lesson-12-banks-and-their-customers" tabindex="-1">第四册：流利英语 · Lesson 12 Banks and their customers <a class="header-anchor" href="#第四册-流利英语-·-lesson-12-banks-and-their-customers" aria-label="Permalink to &quot;第四册：流利英语 · Lesson 12 Banks and their customers&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-02/overview">单元 2</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>围绕银行服务中的条款、客户预期与沟通责任，练习读取条件句而不只看结论。将“如果满足条件才会发生”与“必然发生”区分开来。课堂情境仅用于语言练习，不代表真实机构的合同或现行政策；输出要清楚交代触发条件与后续步骤。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>account</td><td>/əˈkaʊnt/</td><td>n.</td><td>账户</td><td>open an account</td></tr><tr><td>deposit</td><td>/dɪˈpɒzɪt/</td><td>n.</td><td>存款</td><td>make a deposit</td></tr><tr><td>statement</td><td>/ˈsteɪtmənt/</td><td>n.</td><td>对账单</td><td>a monthly statement</td></tr><tr><td>condition</td><td>/kənˈdɪʃən/</td><td>n.</td><td>条件</td><td>meet a condition</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>subject to — 以满足某条件为前提</li><li>in writing — 以书面形式</li></ul><h2 id="语法讲解-unless-与条件从句" tabindex="-1">语法讲解：unless 与条件从句 <a class="header-anchor" href="#语法讲解-unless-与条件从句" aria-label="Permalink to &quot;语法讲解：unless 与条件从句&quot;">​</a></h2><p>unless 通常表示 if…not，即除非某条件成立，否则主句成立。The request will remain pending unless you sign. 意为不签字就继续待处理。unless 从句谈未来通常用一般现在时，不写 unless you will sign。并非所有含否定的 if 句都能机械改为 unless，尤其反事实或否定本身是讨论焦点时。阅读条款应先写出条件成立与不成立的两条结果，再检查逻辑。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>In this exercise, the request will remain pending unless the customer signs the form.</p></blockquote><p>在本练习中，除非客户签署表格，否则申请将保持待处理状态。</p><p>unless 引出例外条件；signs 用现在时表未来条件；主句 will remain 表结果。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>unless the customer will sign 不用于这里的普通未来条件；应写 signs。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>朗读 unless 前短停，重读 included；随后用 if not 复述一次，检查听到否定时是否仍能判断结果。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Please attach a copy of your identification. The request will remain pending unless the copy is included. Contact the service desk if you need help with the form.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>为虚构服务台写三句申请说明：所需文件、缺失时的结果、咨询方式。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>申请条件和未满足的后果分别表达，第三句提供行动入口。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>将 unless the customer signs 改为 if 结构。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> if the customer does not sign</p><p><strong>解析：</strong> unless 在本句等于 if not。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>按示例，客户不签字时申请是什么状态？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 仍待处理。</p><p><strong>解析：</strong> 这是 unless 条件不成立时主句所述结果。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>填空：We will send a copy if you ___ one.（request）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> request</p><p><strong>解析：</strong> 条件从句用一般现在时表示未来。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：unless 与条件从句。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-4/unit-02/grammar">单元语法</a> · <a href="/life/english/new-concept/book-4/unit-02/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-4/unit-02/review">单元自测</a></p><p><a href="/life/english/new-concept/book-4/unit-02/lesson-011">上一课</a> · <a href="/life/english/new-concept/book-4/unit-02/overview">单元目录</a> · <a href="/life/english/new-concept/book-4/unit-02/lesson-013">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const m=t(o,[["render",i]]);export{p as __pageData,m as default};
